import json, statistics as st, datetime
rows = json.load(open("online_mealprep.json"))
def agg(store):
    r = [x for x in rows if x["store"] == store]
    if not r: return None
    e = [x["eur_per_10g_protein"] for x in r if x["eur_per_10g_protein"]]
    return {"n_products": len(r), "median_price_eur": round(st.median(x["price_eur"] for x in r if x["price_eur"]), 2) if any(x["price_eur"] for x in r) else None, "median_eur_per_10g_protein": round(st.median(e), 2) if e else None, "best_eur_per_10g_protein": min(e) if e else None, "median_protein_pack_g": round(st.median(x["protein_pack"] for x in r), 1)}
